    opPoint(context, id + "p3", { "point" : vector(0, 30, 0) * millimeter });
    opPoint(context, id + "p4", { "point" : vector(40, 30, 0) * millimeter });
    constrainedSurface(context, id + "surface1", { "csType" : ConstrainedSurfaceType.POINTS, "vertices" : [{ "vertex" : qCreatedBy(id + "p1", EntityType.VERTEX), "normal" : qNothing(), "flipNormal" : false }, { "vertex" : qCreatedBy(id + "p2", EntityType.VERTEX), "normal" : qNothing(), "flipNormal" : false }, { "vertex" : qCreatedBy(id + "p3", EntityType.VERTEX), "normal" : qNothing(), "flipNormal" : false }, { "vertex" : qCreatedBy(id + "p4", EntityType.VERTEX), "normal" : qNothing(), "flipNormal" : false }], "tolerance" : 0.01 * millimeter, "optimize" : OptimizationMethod.SMOOTH, "computeDeviation" : false });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "surface1", EntityType.BODY), BodyType.SHEET)) };
}

